# custo-tags.tf — ativar a chave, que e o passo que quase todo mundo esquece

# A tag no recurso NAO e uma dimensao de custo. Ela passa a ser depois de
# ativada, e o relogio disto e documentado: ate 24 h para a chave APARECER na
# pagina de tags de alocacao e ate outras 24 h para ela FICAR ATIVA. Nesse
# intervalo, filtro por tag no Cost Explorer e orcamento por tag devolvem vazio
# sem erro nenhum — e o diagnostico errado obvio e "a tag nao funciona".
resource "aws_ce_cost_allocation_tag" "taxonomia" {
  for_each = toset(["Ambiente", "Componente", "Dono", "Origem"])

  tag_key = each.value
  status  = "Active"
}

# Ativar tag NAO cria recurso cobrado, mas consome cota: existe um maximo de
# chaves ativas para os relatorios de faturamento. Veja o valor atual em
# Service Quotas / Quotas and restrictions em vez de decorar um numero.

# Categoria de custo: a saida honesta para explicar o PASSADO.
#
# Tag nao retroage no recurso. Categoria de custo, sim: a data efetiva pode ser
# o primeiro dia de um mes de ate 12 meses atras, e a regra e aplicada
# retroativamente. E ela nao depende de tag — as dimensoes que ela usa (servico,
# tipo de uso, regiao, conta) sempre existiram no dado.
#
# Por isso a Cadencia consegue reconstruir marco a junho por PECA, mesmo sem
# nenhuma tag naquele periodo. E a unica reconstrucao possivel, e ela chega ao
# nivel de tipo de uso — nao ao de "qual dos dois ambientes".
resource "aws_ce_cost_category" "peca" {
  name          = "Peca"
  rule_version  = "CostCategoryExpression.v1"
  effective_start = var.mes_inicial_retroativo # ex.: "2026-03-01T00:00:00Z"

  # O tipo de uso vem prefixado pela regiao (`USE1-NatGateway-Bytes`), e e por
  # isso que o casamento e por sufixo. Quais `match_options` cada dimensao aceita
  # varia: confira na referencia de expressao de categoria de custo antes de
  # assumir, porque opcao invalida falha no `apply` e opcao valida que casa com
  # nada falha em silencio — o segundo e o caro.
  rule {
    value = "rede"
    rule {
      dimension {
        key           = "USAGE_TYPE"
        values        = ["NatGateway-Hours", "NatGateway-Bytes", "VpcEndpoint-Hours", "VpcEndpoint-Bytes"]
        match_options = ["ENDS_WITH"]
      }
    }
  }

  rule {
    value = "observabilidade"
    rule {
      dimension {
        key    = "SERVICE"
        values = ["AmazonCloudWatch"]
      }
    }
  }

  rule {
    value = "banco"
    rule {
      dimension {
        key    = "SERVICE"
        values = ["Amazon Relational Database Service"]
      }
    }
  }

  # Sem esta linha, tudo o que nao casou com regra alguma fica como nao
  # categorizado — que e informacao, nao defeito: mede o quanto do gasto o seu
  # recorte ainda nao explica.
  default_value = "nao-classificado"
}

# orcamento.tf — o alerta que chega ANTES, e o topico que costuma nao entregar

resource "aws_sns_topic" "custo" {
  name = "${var.projeto}-alerta-custo"
}

# A falha silenciosa numero um de toda esta montagem. O Budgets publica no topico
# como um SERVICO, nao como voce: sem esta politica, o orcamento estoura, a
# notificacao e tentada, falha, e ninguem e avisado de nada. O sintoma e "criei o
# orcamento e nunca recebi e-mail" — e o orcamento esta correto.
data "aws_iam_policy_document" "topico_custo" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["budgets.amazonaws.com"]
    }
    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.custo.arn]

    # Confused deputy: sem esta condicao, o principal de servico do Budgets de
    # QUALQUER conta poderia publicar no seu topico.
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.atual.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "custo" {
  arn    = aws_sns_topic.custo.arn
  policy = data.aws_iam_policy_document.topico_custo.json
}

# ── Orcamento 1: a conta inteira, como rede de seguranca ─────────────────────
resource "aws_budgets_budget" "conta" {
  name         = "${var.projeto}-conta"
  budget_type  = "COST"
  limit_amount = var.limite_conta # valor definido por VOCE, no seu contexto
  limit_unit   = var.moeda
  time_unit    = "MONTHLY"

  # Realizado em 80%: registro historico, chega depois do gasto.
  notification {
    comparison_operator        = "GREATER_THAN"
    threshold                  = 80
    threshold_type             = "PERCENTAGE"
    notification_type          = "ACTUAL"
    subscriber_sns_topic_arns  = [aws_sns_topic.custo.arn]
  }

  # PREVISTO em 100%: o unico limiar que avisa enquanto ainda ha mes para reagir.
  # O Budgets reavalia ate tres vezes ao dia, entao "tempo para reagir" e da
  # ordem de horas — nao de minutos.
  notification {
    comparison_operator       = "GREATER_THAN"
    threshold                 = 100
    threshold_type            = "PERCENTAGE"
    notification_type         = "FORECASTED"
    subscriber_sns_topic_arns = [aws_sns_topic.custo.arn]
  }
}

# ── Orcamento 2: por VALOR DE TAG — o entregavel do laboratorio ──────────────
resource "aws_budgets_budget" "por_componente" {
  for_each = var.limite_por_componente # { api = "...", banco = "...", rede = "..." }

  name         = "${var.projeto}-componente-${each.key}"
  budget_type  = "COST"
  limit_amount = each.value
  limit_unit   = var.moeda
  time_unit    = "MONTHLY"

  # O formato e `user:<chave>$<valor>`. O prefixo `user:` nao e enfeite: a
  # documentacao de filtros de orcamento e explicita ao dizer que chave definida
  # por usuario usa esse prefixo no dado de faturamento — e que a tag precisa
  # estar ATIVADA para servir de filtro. Filtro sobre chave inativa nao da erro:
  # da zero.
  # `format` em vez de interpolacao direta porque o `$` do formato colide com a
  # sintaxe `${...}` do HCL: escrever `"...$${each.key}"` produziria o literal
  # `${each.key}`, e o filtro casaria com nada — em silencio, devolvendo zero.
  cost_filter {
    name   = "TagKeyValue"
    values = [format("user:Componente$%s", each.key)]
  }

  notification {
    comparison_operator       = "GREATER_THAN"
    threshold                 = 100
    threshold_type            = "PERCENTAGE"
    notification_type         = "FORECASTED"
    subscriber_sns_topic_arns = [aws_sns_topic.custo.arn]
  }

  depends_on = [aws_ce_cost_allocation_tag.taxonomia]
}

# ── Orcamento 3: de USO, nao de custo — para a dimensao que engana ───────────
# Orcamento de uso limita a QUANTIDADE de uma unidade de medida. Aqui ele vigia
# GB processados pelo NAT: se esse numero dispara, houve mudanca de comportamento
# da aplicacao, e isso e informacao diferente de "gastei mais".
resource "aws_budgets_budget" "nat_gb" {
  name         = "${var.projeto}-nat-gb"
  budget_type  = "USAGE"
  limit_amount = var.limite_nat_gb
  limit_unit   = "GB"
  time_unit    = "MONTHLY"

  cost_filter {
    name   = "UsageType"
    values = ["${var.prefixo_regiao}-NatGateway-Bytes"]
  }

  notification {
    comparison_operator       = "GREATER_THAN"
    threshold                 = 100
    threshold_type            = "PERCENTAGE"
    notification_type         = "FORECASTED"
    subscriber_sns_topic_arns = [aws_sns_topic.custo.arn]
  }
}

# ── Deteccao de anomalia: pega o que nenhum limite previu ────────────────────
resource "aws_ce_anomaly_monitor" "servicos" {
  name              = "${var.projeto}-por-servico"
  monitor_type      = "DIMENSIONAL"
  monitor_dimension = "SERVICE"
}

resource "aws_ce_anomaly_subscription" "servicos" {
  name      = "${var.projeto}-anomalia"
  frequency = "DAILY"
  monitor_arn_list = [aws_ce_anomaly_monitor.servicos.arn]

  subscriber {
    type    = "SNS"
    address = aws_sns_topic.custo.arn
  }

  # O limiar por EXPRESSAO evita ruido: so avisa quando o impacto absoluto do
  # desvio passa do valor que VOCE considera relevante.
  threshold_expression {
    dimension {
      key           = "ANOMALY_TOTAL_IMPACT_ABSOLUTE"
      match_options = ["GREATER_THAN_OR_EQUAL"]
      values        = [var.impacto_minimo_anomalia]
    }
  }
}

// Servicos/RateioPorTag.cs — le o custo agrupado por valor de tag.
//
// Por que isto vive na aplicacao e nao num script: o numero que importa nao e o
// custo, e o custo POR PEDIDO. O denominador esta no banco desta aplicacao, e
// juntar as duas metades em qualquer outro lugar exigiria copiar dado de negocio
// para fora.

using Amazon;
using Amazon.CostExplorer;
using Amazon.CostExplorer.Model;
using Microsoft.Extensions.Caching.Memory;

namespace Pedidos.Servicos;

public sealed record FatiaDeCusto(string Valor, decimal Custo);

public sealed record Rateio(
    IReadOnlyList<FatiaDeCusto> Fatias,
    decimal Total,
    decimal SemValorDeTag,
    double PercentualSemDono);

public sealed class RateioPorTag(
    IAmazonCostExplorer ce,
    IMemoryCache cache,
    ILogger<RateioPorTag> log)
{
    // O dado de faturamento e atualizado no maximo uma vez por dia. Consultar de
    // novo antes disso gasta requisicao paga e devolve o MESMO numero: o cache
    // aqui nao e otimizacao, e coerencia com a taxa de atualizacao da fonte.
    private static readonly TimeSpan Janela = TimeSpan.FromHours(6);

    public async Task<Rateio> DoMesAsync(string chave, CancellationToken ct)
    {
        var hoje = DateTime.UtcNow.Date;
        var inicio = new DateTime(hoje.Year, hoje.Month, 1);

        return (await cache.GetOrCreateAsync($"rateio:{chave}:{inicio:yyyy-MM}", async entrada =>
        {
            entrada.AbsoluteExpirationRelativeToNow = Janela;
            return await ConsultarAsync(chave, inicio, hoje.AddDays(1), ct);
        }))!;
    }

    private async Task<Rateio> ConsultarAsync(
        string chave, DateTime de, DateTime ate, CancellationToken ct)
    {
        var pedido = new GetCostAndUsageRequest
        {
            TimePeriod = new DateInterval
            {
                Start = de.ToString("yyyy-MM-dd"),
                End = ate.ToString("yyyy-MM-dd") // fim EXCLUSIVO
            },
            Granularity = Granularity.MONTHLY,

            // UnblendedCost e a taxa que a conta pagou pelo uso. Em conta unica sem
            // compromisso comprado, ele coincide com o amortizado; a distincao passa
            // a importar quando houver Savings Plans, e ai o assunto e o L59.
            Metrics = ["UnblendedCost"],

            GroupBy =
            [
                new GroupDefinition { Type = GroupDefinitionType.TAG, Key = chave }
            ]
        };

        var fatias = new List<FatiaDeCusto>();
        decimal semDono = 0m;

        // Paginacao explicita: cada requisicao paginada da API do Cost Explorer e
        // cobrada. Vale saber disso antes de colocar a chamada num laco de painel
        // que atualiza a cada 30 segundos.
        string? proxima = null;
        do
        {
            pedido.NextPageToken = proxima;
            var r = await ce.GetCostAndUsageAsync(pedido, ct);

            foreach (var grupo in r.ResultsByTime.SelectMany(t => t.Groups))
            {
                // A chave do grupo vem como "Componente$api". Quando o recurso nao
                // tinha a tag na hora do gasto, ela vem como "Componente$" — o
                // valor vazio. Este e o balde sem dono, e ele e a medida mais
                // honesta da qualidade da sua instrumentacao.
                var bruto = grupo.Keys[0];
                var valor = bruto.Contains('$') ? bruto[(bruto.IndexOf('$') + 1)..] : bruto;
                var custo = decimal.Parse(
                    grupo.Metrics["UnblendedCost"].Amount,
                    System.Globalization.CultureInfo.InvariantCulture);

                if (string.IsNullOrEmpty(valor)) semDono += custo;
                else fatias.Add(new FatiaDeCusto(valor, custo));
            }

            proxima = r.NextPageToken;
        } while (!string.IsNullOrEmpty(proxima));

        var total = fatias.Sum(f => f.Custo) + semDono;
        var percentual = total == 0 ? 0 : (double)(semDono / total) * 100;

        if (percentual > 5)
        {
            // Acima disto o rateio nao e confiavel e o orcamento por tag mente para
            // baixo. Registrar como aviso e o que impede alguem apresentar o grafico
            // como se ele fechasse.
            log.LogWarning(
                "Rateio por {Chave} com {Percentual:F1}% sem valor de tag: o orcamento por tag esta subestimado",
                chave, percentual);
        }

        return new Rateio(
            fatias.OrderByDescending(f => f.Custo).ToList(), total, semDono, percentual);
    }
}

// Program.cs — o cliente, a rota interna e o custo por pedido

using Amazon;
using Amazon.CostExplorer;
using Pedidos.Servicos;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMemoryCache();

// O endpoint do Cost Explorer e GLOBAL e atendido em us-east-1: o dado de
// faturamento nao e regional. Configurar o cliente com a regiao da aplicacao faz
// a chamada falhar por endpoint inexistente, e o erro nao menciona faturamento.
builder.Services.AddSingleton<IAmazonCostExplorer>(_ =>
    new AmazonCostExplorerClient(new AmazonCostExplorerConfig
    {
        RegionEndpoint = RegionEndpoint.USEast1
    }));

builder.Services.AddSingleton<RateioPorTag>();

var app = builder.Build();

// Rota INTERNA. Custo e dado sensivel de negocio: ela nao vai para o CloudFront,
// e o caminho fica atras da autenticacao que o L12 constroi. Enquanto isso, ela
// so responde na rede privada.
app.MapGet("/interno/rateio", async (
        RateioPorTag rateio, IContagemDePedidos pedidos, CancellationToken ct) =>
    {
        var r = await rateio.DoMesAsync("Componente", ct);
        var quantidade = await pedidos.DoMesAtualAsync(ct);

        return Results.Ok(new
        {
            porComponente = r.Fatias,
            total = r.Total,
            semDono = r.SemValorDeTag,
            percentualSemDono = Math.Round(r.PercentualSemDono, 1),

            // O indicador que sobe ou desce independente do total. Ele e o unico
            // numero desta resposta que serve para decidir alguma coisa.
            custoPorMilPedidos = quantidade == 0
                ? (decimal?)null
                : Math.Round(r.Total / quantidade * 1000, 4),

            // Sem esta linha, alguem vai ler o numero de hoje como sendo de hoje.
            atualizadoAte = "o dado de faturamento e atualizado ao menos uma vez por dia"
        });
    })
    .WithName("RateioInterno");

app.Run();
